import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        a = list(map(int, data[idx:idx+n]))
        idx += n

        dp = [0] * (n + 1)

        for i in range(n, 0, -1):
            if i + a[i-1] <= n:
                dp[i] = a[i-1] + dp[i + a[i-1]]
            else:
                dp[i] = a[i-1]

        results.append(str(max(dp)))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

