import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Read the matrix
    matrix = []
    idx = 2
    for i in range(n):
        row = data[idx]
        matrix.append(row)
        idx += 1

    # Check each switch
    for i in range(n):
        # Lamps turned on by all switches except switch i
        lamps_on = set()
        for j in range(n):
            if j == i:
                continue
            for k in range(m):
                if matrix[j][k] == '1':
                    lamps_on.add(k)

        if len(lamps_on) == m:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    solve()
"}

