def solve():
    n, m, k = map(int, input().split())
    matrix = []
    for _ in range(n):
        row = list(map(int, input().split()))
        matrix.append(row)

    # For each column, find the topmost 1
    topmost_ones = []
    for j in range(m):
        for i in range(n):
            if matrix[i][j] == 1:
                topmost_ones.append((i, j))
                break

    # Calculate score and replacements
    score = 0
    replacements = 0

    for i, j in topmost_ones:
        # Count 1s in next min(k, n-i) elements (including the topmost one)
        count = 0
        for idx in range(i, min(i + k, n)):
            if matrix[idx][j] == 1:
                count += 1
        score += count

    print(score, replacements)

