import math

def has_same_pattern(s1, s2):
    """Check if two strings have the same character pattern"""
    return s1 == s2  # Since we're only using 'a' and 'b', we can just compare directly

q = int(input())
for _ in range(q):
    s = input().strip()
    t = input().strip()

    if not has_same_pattern(s, t):
        print(-1)
    else:
        l = math.lcm(len(s), len(t))
        result = s * (l // len(s))
        print(result)
