def find_pattern(s):
    """Find the smallest repeating pattern of a string s"""
    length = len(s)
    for divisor in range(1, length + 1):
        if length % divisor == 0:
            # Check if the pattern of length divisor repeated (length // divisor) times equals s
            pattern = s[:divisor]
            repeated = pattern * (length // divisor)
            if repeated == s:
                return pattern
    return s

q = int(input())
for _ in range(q):
    s = input().strip()
    t = input().strip()

    pattern_s = find_pattern(s)
    pattern_t = find_pattern(t)

    if pattern_s != pattern_t:
        print(-1)
    else:
        lcm_length = math.lcm(len(s), len(t))
        result = pattern_s * lcm_length
        print(result)
"}

