def solve():
    n, k = map(int, input().split())

    # Calculate the number of positions in the upper triangle
    count = n * (n + 1) // 2

    if k > count:
        print(-1)
        return

    # We need to consider the upper triangle in the correct order:
    # (0,0), (0,1)-(1,0), (0,2)-(2,0), (1,1), (1,2)-(2,1), (2,2), etc.

    matrix = [[0 for _ in range(n)] for _ in range(n)]

    for i in range(n):
        for j in range(i, n):
            # Calculate how many ones we can place here
            if i < j:
                # We can place 0 or 2 ones
                if k >= 2:
                    matrix[i][j] = 1
                    matrix[j][i] = 1
                    k -= 2
            else:  # i == j
                # We can place 0 or 1 one
                if k >= 1:
                    matrix[i][j] = 1
                    k -= 1

    for row in matrix:
        print(' '.join(map(str, row)))

solve()
