MOD = 10**9 + 7

def is_perfect_square(x):
    if x == 0:
        return True
    root = int(x**0.5)
    return root * root == x

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Precompute squares up to max possible product
    max_val = max(a) * max(a)
    squares = set()
    root = int(max_val**0.5)
    for i in range(1, root + 1):
        squares.add(i * i)

    # DP: dp[mask][last] = number of ways
    from collections import defaultdict
    dp = [defaultdict(int) for _ in range(1 << n)]

    for i in range(n):
        dp[1 << i][i] = 1

    for mask in range(1 << n):
        for last, count in dp[mask].items():
            if count == 0:
                continue
            for next in range(n):
                if not (mask & (1 << next)):
                    # Check if product is perfect square
                    product = a[last] * a[next]
                    if product in squares:
                        continue
                    dp[mask | (1 << next)][next] = (dp[mask | (1 << next)][next] + count) % MOD

    full_mask = (1 << n) - 1
    result = sum(dp[full_mask][i] for i in range(n)) % MOD
    print(result)

solve()
