    for i in range(1, root + 1):
        squares.add(i * i)
    return squares

# For checking if product is perfect square
def is_perfect_square_product(a, b, squares):
    product = a * b
    if product in squares:
        return True
    return False

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    squares = precompute_squares()

    # Count occurrences of each unique value
    value_counts = {}
    for num in a:
        if num not in value_counts:
            value_counts[num] = 0
        value_counts[num] += 1

    # Get unique values
    unique_values = list(value_counts.keys())
    m = len(unique_values)

    # Precompute which values can be adjacent
    adjacency = [[] for _ in range(m)]
    for i in range(m):
        for j in range(m):
            val1 = unique_values[i]
            val2 = unique_values[j]
            if not is_perfect_square_product(val1, val2, squares):
                adjacency[i].append(j)

    # DP: dp[mask] = dictionary {last: count}
    # mask: integer representing which unique values have been used
    dp = [{} for _ in range(1 << m)]

    for i in range(m):
        dp[1 << i][i] = value_counts[unique_values[i]]

    for mask in range(1 << m):
        for last, count in dp[mask].items():
            if count == 0:
                continue
            for next in adjacency[last]:
                new_mask = mask | (1 << next)
                new_last = next
                dp[new_mask][new_last] = (dp[new_mask][new_last] + count) % MOD

    full_mask = (1 << m) - 1
    result = 0
    for last, count in dp[full_mask].items():
        result = (result + count) % MOD

    print(result)

