import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    h = int(data[idx])
    idx += 1
    w = int(data[idx])
    idx += 1

    grid = []
    for _ in range(h):
        grid.append(data[idx])
        idx += 1

    # Find all '*' positions
    stars = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '*':
                stars.append((i, j))

    if not stars:
        print("NO")
        return

    # Try each star as potential center
    for (cx, cy) in stars:
        # Check if this star could be the center

        # Check if there's a ray going up
        up = True
        for i in range(cx - 1, -1, -1):
            if grid[i][cy] != '*':
                up = False
                break

        # Check if there's a ray going down
        down = True
        for i in range(cx + 1, h):
            if grid[i][cy] != '*':
                down = False
                break

        # Check if there's a ray going left
        left = True
        for j in range(cy - 1, -1, -1):
            if grid[cx][j] != '*':
                left = False
                break

        # Check if there's a ray going right
        right = True
        for j in range(cy + 1, w):
            if grid[cx][j] != '*':
                right = False
                break

        if up and down and left and right:
            # Check if there are any other '*' outside these rays
            valid = True
            for i in range(h):
                for j in range(w):
                    if grid[i][j] == '*':
                        # Check if this star is part of the rays
                        if i == cx:
                            # Horizontal ray, check if in left or right
                            if j >= cy - 1 and j <= cy + 1:
                                continue
                            else:
                                valid = False
                                break
                        elif j == cy:
                            # Vertical ray, check if in up or down
                            if i >= cx - 1 and i <= cx + 1:
                                continue
                            else:
                                valid = False
                                break
                        else:
                            valid = False
                            break
                if not valid:
                    break

            if valid:
                print("YES")
                return

    print("NO")

if __name__ == "__main__":
    solve()
