def mod_pow(base, exp, mod):
    """Fast modular exponentiation"""
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp //= 2
    return result

def solve():
    MOD = 10**9 + 7

    k = int(input())
    a = list(map(int, input().split()))

    # n is the product of all elements
    # n can be very large, but we only need parity
    # Check if n is even or odd
    is_even = True
    for num in a:
        if num % 2 == 1:
            is_even = False

    # n
    power = mod_pow(2, k, MOD)
    # Wait, we need 2^n, not 2^{n-1}
    power = mod_pow(2, k, MOD)

    # 2 * (-1)^{n-1}
    if is_even:
        # n is even, 2 * (-1)^{n-1} = 2 * (-1)^{odd} = -2
        term = -2
    else:
        # n is odd, 2 * (-1)^{n-1} = 2 * (-1)^{even} = 2
        term = 2

    # Numerator = 2^n + 2 * (-1)^{n-1}
    numerator = (power + term + MOD) % MOD

    # Denominator = 3 * 2^n
    denominator = (3 * power) % MOD

    print(f"{numerator}/{denominator}")

solve()
