        columns = []
        for _ in range(m):
            col = [int(next(it)) for _ in range(n)]
            columns.append(col)

        # Try to match rows with columns
        # For each row, we need to find a column it can match with
        # A row matches a column if there exists some position i where the elements match,
        # and the rest of the elements match in their respective positions

        used_columns = [False] * m

        # Try to match each row with a column
        for i in range(n):
            found = False
            for j in range(m):
                if not used_columns[j]:
                    # Check if row i matches column j
                    match = True

                    # Try to match at position k
                    for k in range(n):
                        # Check if row i can match column j at position k
                        if rows[i][k] == columns[j][k]:
                            # Check if the rest of the elements match
                            matched = True
                            for l in range(n):
