# Start with student 1 knowing the news
knows_news = {1}
capacity = a[:]

# List to store messages
messages = []

# Queue of students who know the news
queue = [1]

while queue:
    sender = queue.pop(0)
    # Try to send messages from this student
    for receiver in range(1, n + 1):
        if receiver not in knows_news and capacity[receiver - 1] > 0:
            # This student can receive
            if capacity[sender - 1] > 0:
                # Sender can send
                messages.append((sender, receiver))
                knows_news.add(receiver)
                capacity[receiver - 1] -= 1
                capacity[sender - 1] -= 1
                queue.append(receiver)
            else:
                # Sender is out of capacity
                break

if len(knows_news) == n:
