import sys

def get_fingerprint(k):
    """Compute the fingerprint of key k"""
    fingerprint = []
    current = k
    d = 2

    while True:
        remainder = current % d
        current = current // d
        fingerprint.append(remainder)

        if current == 0:
            break

        d += 1

    return tuple(fingerprint)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    keys = list(map(int, data[1:1+t]))

    # Compute fingerprint for each key
    fingerprints = {}
    for key in keys:
        fp = get_fingerprint(key)
        if fp not in fingerprints:
            fingerprints[fp] = []
        fingerprints[fp].append(key)

