import sys
sys.setrecursionlimit(1 << 25)
from itertools import combinations

def solve():
    n = int(sys.stdin.readline())
    tree = [[] for _ in range(n + 1)]
    efficiencies = [0] * (n + 1)

    for i in range(1, n + 1):
        pi, ai = map(int, sys.stdin.readline().split())
        if pi == -1:
            root = i
        else:
            tree[pi].append(i)
        efficiencies[i] = ai

    def dfs(node):
        child_efficiencies = []
        for child in tree[node]:
            child_eff = dfs(child)
            child_efficiencies.append((child_eff, child))

        max_not = 0  # max efficiency without including node
        max_yes = 0  # max efficiency with including node

        # Try all combinations for case where we don't include node
        for k in range(len(child_efficiencies) + 1):
            if k % 2 == 1:
                max_not = max(max_not, sum(c[0] for c in combinations(child_efficiencies, k)))

        # Try all combinations for case where we include node
        for k in range(len(child_efficiencies) + 1):
            if k % 2 == 0:
                max_yes = max(max_yes, sum(c[0] for c in combinations(child_efficiencies, k)) + efficiencies[node])

        return max_not, max_yes

    max_not, max_yes = dfs(root)
    print(max(max_not, max_yes))

solve()
