def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    switches = []
    idx = 2

    for _ in range(n):
        switches.append(data[idx])
        idx += 1

    # For each lamp, count how many switches control it
    lamp_coverage = [0] * m
    for i in range(n):
        for j in range(m):
            if switches[i][j] == '1':
                lamp_coverage[j] += 1

    # Check if there exists an ignorable switch
    ignorable = True
    for i in range(n):
        # For switch i to be ignorable, for every lamp it controls,
        # there must be at least one other switch that also controls it
        for j in range(m):
            if switches[i][j] == '1' and lamp_coverage[j] == 1:
                ignorable = False
                break
        if not ignorable:
            break

    print("YES" if ignorable else "NO")

if __name__ == "__main__":
    solve()
