    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    switches = []
    idx = 2

    for _ in range(n):
        switches.append(data[idx])
        idx += 1

    # For each lamp, count how many switches control it
    lamp_coverage = [0] * m
    for i in range(n):
        for j in range(m):
            if switches[i][j] == '1':
                lamp_coverage[j] += 1

    # Check if there exists an ignorable switch
    # A switch is ignorable if there exists at least one lamp that it controls,
    # and that lamp is also controlled by at least one other switch
    for i in range(n):
        for j in range(m):
            if switches[i][j] == '1' and lamp_coverage[j] > 1:
                print("YES")
                return

    print("NO")

if __name__ == "__main__":
    solve()

