def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    switches = []
    idx = 2

    for _ in range(n):
        switches.append(data[idx])
        idx += 1

    # For each lamp, count how many switches control it
    lamp_coverage = [0] * m
    for i in range(n):
        for j in range(m):
            if switches[i][j] == '1':
                lamp_coverage[j] += 1

    # Check if there exists an ignorable switch
    for i in range(n):
        # Check if we can ignore switch i
        # For lamp j, if only switch i controls it, we need to ensure
        # that lamp j can be turned on by other switches if switch i is ignored
        can_ignore = True

        # Check all lamps
        for j in range(m):
            if switches[i][j] == '1':  # Lamp j is controlled by switch i
                # Count how many switches control lamp j (excluding switch i)
                count = 0
                for k in range(n):
                    if k != i and switches[k][j] == '1':
                        count += 1

                # If no other switch controls lamp j, we can't ignore switch i
                if count == 0:
                    can_ignore = False
                    break

        if can_ignore:
            print("YES")
            return

    print("NO")

