import math

def lcm(a, b):
    return a * b // math.gcd(a, b)

def string_divides(divisor, dividend):
    if len(dividend) % len(divisor) != 0:
        return False
    for i in range(len(dividend) // len(divisor)):
        if dividend[i * len(divisor): (i+1)*len(divisor)] != divisor:
            return False
    return True

def find_lcm_string(s, t):
    # If one string divides the other
    if string_divides(t, s):
        return s
    if string_divides(s, t):
        return t

    # Calculate LCM of lengths
    lcm_len = lcm(len(s), len(t))

    # Check if there's a common string that both divide
    # The LCM string should have both as divisors
    # We need to find a string of length lcm_len that both divide
    for i in range(1, lcm_len // len(s) + 1):
        candidate = s * i
        if len(candidate) == lcm_len and string_divides(t, candidate):
            return candidate

    for i in range(1, lcm_len // len(t) + 1):
        candidate = t * i
        if len(candidate) == lcm_len and string_divides(s, candidate):
            return candidate

    return -1

q = int(input())
for _ in range(q):
    s = input().strip()
    t = input().strip()

    result = find_lcm_string(s, t)

    if result == -1:
        print(-1)
    else:
        print(result)
