    lcm_len = lcm(len(s), len(t))

    # Check if there's a common string that both divide
    # The LCM string should have both as divisors
    # We need to find a string of length lcm_len that both divide
    for i in range(1, lcm_len // len(s) + 1):
        candidate = s * i
        if len(candidate) == lcm_len and string_divides(t, candidate):
