    # Check if we can place n plates
    # Distance between adjacent plate centers should be >= 2r
    # The circle has radius (R - r)
    circumference = 2 * math.pi * (R - r)
    required_length = 2 * r * n

    if circumference >= required_length:
        print("YES")
    else:
        print("NO")
