import math

n, R, r = map(int, input().split())

s = R - r

if n == 1:
    if R >= r:
        print("YES")
    else:
        print("NO")
elif n == 0:
    # Not possible for n=0
    print("NO")
else:
    # Check if we can place n plates
    # Distance between adjacent plate centers should be >= 2r
    # The circle has radius (R - r)
    # Chord length = 2 * s * sin(π/n)
    # Need: 2 * s * sin(π/n) >= 2r => s * sin(π/n) >= r
    if s * math.sin(math.pi / n) >= r:
        print("YES")
    else:
        print("NO")
"}

