from collections import deque

def solve():
    # Read input
    n, m, k = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(input().strip()))

    # Find S and T positions
    start = None
    target = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                target = (i, j)

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # State: (row, col, bitmask)
    # We'll store distance and lexicographically smallest path for each state
    dist = {}
    path = {}

    q = deque()
    q.append((start[0], start[1], 0))  # Start at S, no types visited
    dist[(start[0], start[1], 0)] = 0
    path[(start[0], start[1], 0)] = ""

    found = False
    answer_path = None
    answer_dist = float('inf')

    while q:
        r, c, mask = q.popleft()
        current_dist = dist[(r, c, mask)]
        current_path = path[(r, c, mask)]

        # Check if we reached target
        if (r, c) == target:
            if not found or current_dist < answer_dist or (current_dist == answer_dist and current_path < answer_path):
                answer_dist = current_dist
                answer_path = current_path
                found = True
            continue

        # Try all 4 directions
        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check if within bounds
            if 0 <= nr < n and 0 <= nc < m:
                next_pos = (nr, nc)
                next_mask = mask
                next_path = current_path

                # Determine what type we're visiting
                cell = grid[nr][nc]
                if cell == 'S':
                    # Already at S, can't go back
                    continue
                elif cell == 'T':
                    # T doesn't have a type, but we only count S and T once
                    # We only reach T when we're done
                    next_mask = mask
                else:
                    # Lowercase letter
                    next_type = ord(cell) - ord('a')
                    if mask & (1 << next_type):
                        # Already visited this type
                        next_mask = mask
                    else:
                        # New type, update mask if we have space
                        if bin(mask).count('1') < k:
                            next_mask = mask | (1 << next_type)
                        else:
                            # Cannot visit this type
                            continue
                    next_path = current_path + cell

                # Check if we've already found a shorter path to this state
                if (nr, nc, next_mask) in dist:
                    if current_dist + 1 < dist[(nr, nc, next_mask)]:
                        dist[(nr, nc, next_mask)] = current_dist + 1
                        path[(nr, nc, next_mask)] = next_path
                        q.append((nr, nc, next_mask))
                    elif current_dist + 1 == dist[(nr, nc, next_mask)]:
                        # Check lexicographic order
                        if next_path < path[(nr, nc, next_mask)]:
                            path[(nr, nc, next_mask)] = next_path
                else:
                    dist[(nr, nc, next_mask)] = current_dist + 1
                    path[(nr, nc, next_mask)] = next_path
                    q.append((nr, nc, next_mask))

    if found:
        print(answer_path)
    else:
        print("-1")

solve()
