import math
from math import gcd

def lcm(a, b):
    return a * b // gcd(a, b)

q = int(input())
for _ in range(q):
    s = input().strip()
    t = input().strip()
    len_s = len(s)
    len_t = len(t)
    lcm_len = lcm(len_s, len_t)

    # Check if one string is a prefix of the other and the pattern matches
    def is_pattern_match(pattern, full):
        """
        Check if full string is a repetition of pattern.
        Also check if pattern is a prefix of full and the pattern matches.
        """
        if len(full) % len(pattern) != 0:
            return False
        for i in range(len(full)):
            if full[i] != pattern[i % len(pattern)]:
                return False
        return True

    if is_pattern_match(t, s):
        # t divides s
        print(s)
    elif is_pattern_match(s, t):
        # s divides t
        print(t)
    else:
        # Try LCM length
        s_candidate = s * (lcm_len // len_s)
        t_candidate = t * (lcm_len // len_t)
        if s_candidate == t_candidate:
            print(s_candidate)
        else:
            print(-1)
"}

