# Parse original time
hour_str, minute_str = original_time.split(':')

# Generate all valid times based on format
valid_times = []

if format_type == 12:
    # 12-hour format: hours 1-12, minutes 0-59
    for hour in range(1, 13):
        for minute in range(60):
            valid_times.append(f"{hour:02d}:{minute:02d}")
elif format_type == 24:
    # 24-hour format: hours 0-23, minutes 0-59
    for hour in range(24):
        for minute in range(60):
            valid_times.append(f"{hour:02d}:{minute:02d}")

# Find the valid time with minimum differences from original
min_diff = float('inf')
best_time = original_time

for candidate in valid_times:
    # Count differences
    diff = 0
    for i in range(len(candidate)):
        if candidate[i] != original_time[i]:
            diff += 1

    if diff < min_diff:
        min_diff = diff
        best_time = candidate
    elif diff == min_diff:
        # If tie, we can return any, so just keep the first
        pass

print(best_time)
