import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    colors = [0] * (n + 1)
    for i in range(1, n + 1):
        colors[i] = int(next(it))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    # For each color, keep track of vertices with that color
    color_to_vertices = {}
    for i in range(1, n + 1):
        color = colors[i]
        if color not in color_to_vertices:
            color_to_vertices[color] = []
        color_to_vertices[color].append(i)

    # For each color, track its neighboring colors
    color_neighbor_colors = {}
    for color in color_to_vertices:
        color_neighbor_colors[color] = set()

    # For each vertex, look at its neighbors
    for v in range(1, n + 1):
        current_color = colors[v]
        for neighbor in adj[v]:
            neighbor_color = colors[neighbor]
            if current_color != neighbor_color:
                color_neighbor_colors[current_color].add(neighbor_color)

    # Find the color with maximum neighboring diversity
    max_size = -1
    result_color = None

    for color, neighbors in color_neighbor_colors.items():
        size = len(neighbors)
        if size > max_size:
            max_size = size
            result_color = color
        elif size == max_size and color < result_color:
            result_color = color

    print(result_color)

if __name__ == "__main__":
    solve()
"}

