def reflection(n):
    """Return the reflection of n: replace each digit a with (9 - a)"""
    s = str(n)
    reflected = ''.join(str(9 - int(c)) for c in s)
    return int(reflected)

def weight(n):
    """Return the weight: n * reflection(n)"""
    return n * reflection(n)

def max_weight_in_range(l, r):
    """Find maximum weight in range [l, r]"""
    max_weight = 0

    # Check endpoints
    max_weight = max(max_weight, weight(l), weight(r))

    # Check numbers of the form 50...0 and 49...9
    # These are the midpoints of digit ranges
    for k in range(1, 11):  # Check numbers with up to 10 digits
        if k == 1:
            candidates = [4, 5, 9]
        else:
            # 50...0 with k digits
