n, k = map(int, input().split())

# The matrix is n x n, symmetrical with respect to main diagonal
# Each pair (i, j) and (j, i) can have at most one 1
# The diagonal positions (i, i) can have at most one 1 each

# Calculate the maximum number of ones we can place
# We can place at most n ones on the diagonal
# And at most (n*(n-1))/2 pairs off-diagonal (each pair costs 2 ones)
max_ones = 0
for i in range(n):
    for j in range(i, n):
        if i < j:
            max_ones += 1
        else:
            max_ones += 1

# Actually, we can place n ones on the diagonal (each costs 1) and
# up to (n*(n-1))/2 off-diagonal pairs (each pair costs 2)
# So max_ones = n + n*(n-1)/1 (since each off-diagonal pair costs 2 ones, we can place at most n*(n-1)/2 pairs)
# max_ones = n + n*(n-1)//2 * 2 = n + n*(n-1) = n^2

# But wait, the maximum possible number of ones in an n x n matrix with symmetry
# is n (diagonal) + (n-1) + (n-2) + ... + 1 = n(n+1)/2 ones
max_ones = n * (n + 1) // 2

if k > max_ones:
    print(-1)
else:
    matrix = [[0] * n for _ in range(n)]

    # Place 1s in lexicographically maximal way
    # First fill the diagonal positions (i, i)
    for i in range(n):
        if k > 0:
            matrix[i][i] = 1
            k -= 1
        else:
            break

    # Then fill off-diagonal positions (i, j) where i < j
    for i in range(n):
        for j in range(i + 1, n):
            if k > 0:
                matrix[i][j] = 1
                matrix[j][i] = 1
                k -= 2

    for row in matrix:
        print(' '.join(map(str, row)) + ' ')
