import sys

def solve():
    w, m, k = map(int, sys.stdin.read().split())

    if k == 0:
        print(1000000000000000)
        return

    cost = 0
    length = 0

    # Calculate digit length of m
    if m < 10:
        d = 1
    elif m < 100:
        d = 2
    elif m < 1000:
        d = 3
    elif m < 10000:
        d = 4
    elif m < 100000:
        d = 5
    elif m < 1000000:
        d = 6
    elif m < 10000000:
        d = 7
    elif m < 100000000:
        d = 8
    elif m < 1000000000:
        d = 9
    else:
        d = 10

    while True:
        start = 10**(d-1)
        end = 10**d - 1

        # Calculate the range of numbers with this digit length >= m
        real_start = max(m, start)
        if real_start > end:
            break

        # Count of numbers
        count = end - real_start + 1

        # Cost per number
        cost_per = d * k

        # How many we can afford
        remaining = w - cost
        if remaining < 0:
            break

        num_affordable = remaining // cost_per

        # But we can't exceed the range
        num_affordable = min(num_affordable, count)

        length += num_affordable
        cost += num_affordable * cost_per

        # Update m to the next number after this range
        m = real_start + num_affordable

