import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    matrix = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        matrix.append(row)

    # precompute for each column
    columns = []
    for col in range(m):
        orig_ones = [matrix[i][col] for i in range(n)]

        # list of (score, cost) pairs for this column
        pairs = []
        # option: eliminate all
        total_ones = sum(orig_ones)
        pairs.append((0, total_ones))

        # consider each row r as topmost (1-indexed)
        for r in range(1, n+1):
            if orig_ones[r-1] == 1:
                # cost: eliminate all 1s strictly above row r (i < r)
                cost = sum(orig_ones[:r-1])
                # score: sum of 1s from row r to min(r+k-1, n)
                end = min(r + k - 1, n)
                score = sum(orig_ones[r-1:end])
                pairs.append((score, cost))

        columns.append(pairs)

    # DP: dp[score] = min cost
    dp = {0: 0}
    for col_pairs in columns:
        new_dp = {}
        for prev_s, prev_c in dp.items():
            for curr_s, curr_c in col_pairs:
                total_s = prev_s + curr_s
                total_c = prev_c + curr_c
                if total_s not in new_dp or new_dp[total_s] > total_c:
                    new_dp[total_s] = total_c
        dp = new_dp

    if not dp:
        print(0, 0)
        return

    max_score = max(dp.keys())
    min_cost = dp[max_score]
    print(max_score, min_cost)

if __name__ == "__main__":
    solve()
