        parent = -1
    else:
        parent = employees[i][0] - 1  # 0-indexed
    children[parent].append(i)

# Calculate total efficiency of each node and its descendants
# Using post-order traversal (iterative DFS)
total_efficiency = [0] * n
for i in range(n):
