    edges.append((a, b, c))

# Build graph
graph = [[] for _ in range(n + 1)]
for a, b, c in edges:
    graph[a].append((b, c))
    graph[b].append((a, c))

# Prim's algorithm
visited = [False] * (n + 1)
total_cost = 0
edges_used = 0

# Start from employee 1
heap = [(0, 1)]
visited[1] = True

while heap:
    cost, node = heapq.heappop(heap)
    if visited[node]:
        continue
    visited[node] = True
    total_cost += cost
    edges_used += 1

    if edges_used == n - 1:
        break

    for neighbor, edge_cost in graph[node]:
        if not visited[neighbor]:
            heapq.heappush(heap, (edge_cost, neighbor))

