import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    out_lines = []

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        # Read n rows (each with m integers)
        rows = []
        for _ in range(n):
            row = [int(next(it)) for _ in range(m)]
            rows.append(row)

        # Read m columns (each with n integers)
        cols = []
        for _ in range(m):
            col = [int(next(it)) for _ in range(n)]
            cols.append(col)

        # Find the correct ordering
        # For each row, find which column it matches by checking which column
        # has the same numbers in the same order

        # We need to match rows to columns
        # Let's use a dictionary to map each row to its matching column index
        row_to_col = {}
        for i, row in enumerate(rows):
            for j, col in enumerate(cols):
                match = True
                for k in range(m):
                    if row[k] != col[k]:
                        match = False
                        break
                if match:
                    row_to_col[i] = j
                    cols.pop(j)  # Remove the matched column
                    break

        # Reorder rows based on column matches
        matched_rows = []
        for i in range(n):
            matched_rows.append(rows[row_to_col[i]])

        # Output the matched rows
        for row in matched_rows:
            out_lines.append(' '.join(map(str, row)) + ' ')

    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
