def solve():
    n = int(input())
    a = list(map(int, input().split()))
    m = int(input())
    queries = []

    for _ in range(m):
        k, pos = map(int, input().split())
        queries.append((k, pos))

    # dp[l][i] = the lexicographically smallest subsequence of length l ending at position i
    # We'll store tuples of (sum, sequence)
    # But we'll optimize by storing just the positions
    # dp[l][i] = (sum, positions)

    dp = [{} for _ in range(n + 1)]  # dp[length][position] = (sum, positions)

    # For length 1, we just take the element at each position
    for i in range(1, n + 1):
        dp[1][i] = (a[i - 1], [i])

    # Build up solutions for longer lengths
    for length in range(2, n + 1):
        for i in range(1, n + 1):
            # Try to extend a subsequence of length -1 ending before i
            # Actually, we should extend subsequences of length -1 = length-1
            if i > 1:
                for prev_pos, (prev_sum, prev_seq) in dp[length - 1].items():
                    if prev_pos < i:
                        new_seq = prev_seq + [i]
                        new_sum = prev_sum + a[i - 1]
                        dp[length][i] = (new_sum, new_seq)

            # Keep only the lexicographically smallest one
            if i in dp[length]:
                # We already have one, check if we should replace
                pass
            else:
                dp[length][i] = (a[i - 1], [i])

    # Now answer queries
    for k, pos in queries:
        # Find the optimal subsequence of length k
        optimal_positions = None
        optimal_sum = -1

        for pos, (sum_val, seq) in dp[k].items():
            if sum_val > optimal_sum:
                optimal_sum = sum_val
                optimal_positions = seq

        print(a[optimal_positions[pos - 1] - 1])

solve()
