def parse_time(time_str):
    """Parse a time string like '05:00 a.m.' and return total minutes since midnight."""
    time_part, period = time_str.split(' ')[0], time_str.split(' ')[1]
    hh, mm = map(int, time_part.split(':'))

    # Convert to 24-hour format
    if period == 'a.m.':
        if hh == 12:
            hh = 0  # Midnight
    else:  # p.m.
        if hh != 12:
            hh += 12  # Noon

    return hh * 60 + mm

def main():
    n = int(input())
    times = []

    for _ in range(n):
        line = input()
        time_str = line.split('[')[1].split(']')[0]
        times.append(parse_time(time_str))

    days = 1
    current_minute = times[0]
    count = 1

    for i in range(1, n):
        time = times[i]

        if time == current_minute:
            count += 1
        else:
            # We need a new day if we exceed 10 events at this minute
            if count > 10:
                days += 1
                count = 1
            else:
                # Or if we have a different minute
                days += 1
                current_minute = time
                count = 1

    print(days)

if __name__ == "__main__":
    main()
