def solve():
    # Read input
    n, m, k = map(int, input().split())
    grid = []
    start = None
    target = None
    for i in range(n):
        row = input().strip()
        grid.append(row)
        for j, ch in enumerate(row):
            if ch == 'S':
                start = (i, j)
            elif ch == 'T':
                target = (i, j)

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Priority queue: (distance, path, x, y, visited_types)
    import heapq
    pq = []

    # Start from 'S'
    sx, sy = start
    start_types = 0  # No types visited initially
    heapq.heappush(pq, (0, '', sx, sy, start_types))

    # visited: (x, y, visited_types) -> (distance, path)
    visited = {}

    while pq:
        dist, path, x, y, types = heapq.heappop(pq)

        # Check if we've visited this state with equal or shorter distance
        key = (x, y, types)
        if key in visited:
            if dist >= visited[key][0]:
                continue
            # Update with new path if same distance but lexicographically smaller
            if dist == visited[key][0]:
                if path < visited[key][1]:
                    visited[key] = (dist, path)
                continue

        visited[key] = (dist, path)

        # Check if we've reached target
        if x == target[0] and y == target[1]:
            return path

        # Try all directions
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                ch = grid[nx][ny]

                if ch == 'T':
                    # Found target
                    new_path = path
                    new_types = types
                    key = (nx, ny, new_types)

                    # Check if we've visited this state with equal or shorter distance
                    if key in visited:
                        if dist + 1 >= visited[key][0]:
                            continue

                    visited[key] = (dist + 1, new_path)
                    heapq.heappush(pq, (dist + 1, new_path, nx, ny, new_types))
                    continue

                if ch == 'S':
                    continue  # Skip start

                # Check if we can visit this type
                if ch in letter_to_idx:
                    idx = letter_to_idx[ch]
                    if (types >> idx) & 1:  # Already visited this type
                        continue

                    # Check if we have enough types left
                    if bin(types).count('1') == k:
                        continue

                # Calculate new types and path
                new_types = types
                new_path = path
                if ch in letter_to_idx:
                    idx = letter_to_idx[ch]
                    new_types |= (1 << idx)
                    new_path += ch

                key = (nx, ny, new_types)

                # Check if we've visited this state with equal or shorter distance
