def solve():
    n, m = map(int, input().split())

    # For each string, find the minimum cost to get each type
    # And also store the string for later use
    strings = []
    min_digit = []
    min_letter = []
    min_special = []

    for _ in range(n):
        s = input().strip()
        strings.append(s)

        # Find positions for each type
        digit_pos = []
        letter_pos = []
        special_pos = []

        for i, ch in enumerate(s):
            if ch.isdigit():
                digit_pos.append(i + 1)  # 1-indexed
            elif ch.islower():
                letter_pos.append(i + 1)
            elif ch in {'#', '*', '&'}:
                special_pos.append(i + 1)

        # Find minimum cost for each type for this string
        if digit_pos:
            min_digit.append(min(abs(pos - 1) for pos in digit_pos))
        else:
            min_digit.append(float('inf'))

        if letter_pos:
            min_letter.append(min(abs(pos - 1) for pos in letter_pos))
        else:
            min_letter.append(float('inf'))

        if special_pos:
            min_special.append(min(abs(pos - 1) for pos in special_pos))
        else:
            min_special.append(float('inf'))

    # Dynamic programming: state = bitmask of collected types
    # 0: none, 1: digit, 2: letter, 4: special, 3: digit+letter, 5: digit+special, 6: letter+special, 7: all
    # dp[i][state] = minimum cost to consider first i strings and have collected 'state'
    dp = [[float('inf')] * 8 for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for state in range(8):
            if dp[i-1][state] == float('inf'):
                continue

            # Try getting a digit from string i-1
            if min_digit[i-1] + dp[i-1][state] < dp[i][(state & 1) | 1]:
                dp[i][(state & 1) | 1] = min_digit[i-1] + dp[i-1][state]

            # Try getting a letter from string i-1
            if min_letter[i-1] + dp[i-1][state] < dp[i][(state & 2) | 2]:
                dp[i][(state & 2) | 2] = min_letter[i-1] + dp[i-1][state]

            # Try getting a special from string i-1
            if min_special[i-1] + dp[i-1][state] < dp[i][(state & 4) | 4]:
                dp[i][(state & 4) | 4] = min_special[i-1] + dp[i-1][state]

    print(dp[n][7])

