                for c in range(col, n):
                    mat[row][c] ^= mat[rank][c]

        rank += 1

    # Check if system is consistent
    is_consistent = True
    for row in range(rank, n):
        for col in range(n):
            if mat[row][col] == 1:
                is_consistent = False
                break

    # If inconsistent, Valera can win by choosing any set
    if not is_consistent:
        print(n)
        print(' '.join(str(i + 1) for i in range(n)))
        return

    # If consistent, check if there are multiple solutions
    # Find a particular solution
    x = [0] * n
    for row in range(rank):
        # Find pivot column
        pivot_col = -1
        for col in range(n):
            if mat[row][col] == 1:
                pivot_col = col
                break

        # Find the value
        val = a[row]
        for col in range(pivot_col + 1, n):
            if mat[row][col] == 1:
                val ^= x[col]

        x[pivot_col] = val

    # Find the null space (free variables)
    pivot_cols = set()
    for col in range(n):
        for row in range(rank):
            if mat[row][col] == 1:
                pivot_cols.add(col)
                break

    # Null space vectors
    null_space = []
    for col in range(n):
        if col in pivot_cols:
            continue
        null_space.append([1 if c == col else 0 for c in range(n)])

    # General solution: x = x_p + Σ(α_i * v_i)
    # We can just use x_p if it doesn't satisfy all constraints
    for i in range(n):
