            null_vec = null_space[0]
            x = [x[j] ^ null_vec[j] for j in range(n)]
            print(len(x))
            print(' '.join(str(j + 1) for j, val in enumerate(x) if val == 1))
            return

    # x_p doesn't satisfy, we're done
    print(len(x))
    print(' '.join(str(i + 1) for i, xi in enumerate(x) if xi == 1))

