def is_perfect_square(x):
    """Check if x is a perfect square."""
    if x < 0:
        return False
    root = int(math.isqrt(x))
    return root * root == x

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Count frequency of each element
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Total number of distinct permutations
    total = 1
    for count in freq.values():
        total *= count
        total %= MOD

    # DP: dp[mask][last] = number of ways to form a permutation
    # where mask is the set of used elements, and last is the last element
    dp = [[0] * n for _ in range(1 << n)]

    # Base case: only one element used
    for i in range(n):
        dp[1 << i][i] = freq[a[i]]

    for mask in range(1 << n):
        for last in range(n):
            if dp[mask][last] == 0:
                continue

            # Try adding each unused element
            for i in range(n):
                if not (mask & (1 << i)):
