def is_perfect_square(x):
    return int(math.isqrt(x)) ** 2 == x

MOD = 10**9 + 7

def solve():
    import sys
    from collections import defaultdict

    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:]))

    # Count frequency of each number
    freq = defaultdict(int)
    for num in a:
        freq[num] += 1

    # For each index, determine which other indices are NOT forbidden
    # (i.e., product is not a perfect square)
    allowed = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and not is_perfect_square(a[i] * a[j]):
                allowed[i].append(j)

    # Memoization for DP
    memo = {}

    def dp(mask, last_idx):
        if mask == 0:
            return 1

        if (mask, last_idx) in memo:
            return memo[(mask, last_idx)]

        count = 0
        for i in range(n):
            if not (mask & (1 << i)):
                # i-th element hasn't been used
                # Check if it can follow the last element
                if last_idx == -1 or i in allowed[last_idx]:
                    count = (count + dp(mask | (1 << i), i)) % MOD

        memo[(mask, last_idx)] = count
        return count

    # Start with no elements used and no last element
    result = dp(0, -1)
    print(result % MOD)

if __name__ == "__main__":
    solve()
