    for j in range(n):
        # Skip cells that are already filled
        if matrix[i][j] == 1:
            continue

        # If we place a 1 at (i, j), we also need to place one at (j, i)
        if i == j:
            # On the diagonal, only one cell needs a 1
            cost = 1
        else:
            # Off-diagonal, both (i, j) and (j, i) need a 1
            cost = 2

        # Check if we can place this 1
        if k >= cost:
            matrix[i][j] = 1
            matrix[j][i] = 1
            k -= cost

# Check if we used all k ones
if k != 0:
    print(-1)
else:
    # Print the matrix
    for row in matrix:
        print(' '.join(map(str, row)))
