def parse_time(time_str):
    """Parse 12-hour time string to minutes since midnight"""
    # Extract hours and minutes
    hour_part, minute_part = time_str.split(':')[0], time_str.split(':')[1].split(' ')[0]
    hours = int(hour_part)
    minutes = int(minute_part)
    period = time_str.split(':')[1].split(' ')[1]

    # Convert to 24-hour format
    if period == "a.m." and hours == 12:
        hours = 0  # 12:00 a.m. is midnight
    elif period == "p.m." and hours != 12:
        hours += 12  # 1:00 p.m. is 13:00

    return hours * 60 + minutes

def main():
    n = int(input())
    times = []
    for _ in range(n):
        line = input().strip()
        # Extract the time part
        time_str = line.split("[")[1].split("]")[0]
        times.append(time_str)

    # Parse times
    minutes_list = [parse_time(time) for time in times]

    # Track logs per minute
    days = 1
    current_minute = minutes_list[0]
    logs_per_minute = {current_minute: 1}

    for i in range(1, n):
        next_minute = minutes_list[i]

        if next_minute in logs_per_minute:
            # Same minute, increment count
            logs_per_minute[next_minute] += 1
        elif next_minute == current_minute - 1:
            # Time goes backwards, need a new day
            days += 1
            current_minute = next_minute
            logs_per_minute = {next_minute: 1}
        else:
            # Time moves forward
            if logs_per_minute[current_minute] >= 10:
                days += 1
                current_minute = next_minute
                logs_per_minute = {next_minute: 1}
            else:
                current_minute = next_minute
                logs_per_minute[current_minute] = logs_per_minute[current_minute - 1] + 1

    print(days)

if __name__ == "__main__":
    main()
