import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    results = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Check if (i + a[i]) % n are all distinct modulo n
        residues = set()
        ok = True
        for i in range(n):
            r = (i + a[i]) % n
            if r in residues:
                ok = False
                break
            residues.add(r)

        if ok:
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
