n, k = map(int, input().split())

# Create an n x n matrix filled with zeroes
matrix = [[0 for _ in range(n)] for _ in range(n)]

cells = []
# Consider cells where i <= j (upper triangle including diagonal)
for i in range(n):
    for j in range(i, n):
        cells.append((i, j))

# Try to greedily fill cells to maximize lexicographically
for i, j in cells:
    # Determine how many ones this cell would cost
    if i == j:
        cost = 1
    else:
        cost = 2

    # If we have enough ones left, place one here
    if k >= cost:
        matrix[i][j] = 1
        matrix[j][i] = 1
        k -= cost

# Check if we used all k ones
if k != 0:
    print(-1)
else:
    # Print the matrix
    for row in matrix:
        print(' '.join(map(str, row)) + ' ')
