n = int(input())

diagonal_sum = {}
diagonal_diff = {}

for _ in range(n):
    x, y = map(int, input().split())

    # Update counts for both diagonals
    diagonal_sum[x + y] = diagonal_sum.get(x + y, 0) + 1
    diagonal_diff[x - y] = diagonal_diff.get(x - y, 0) + 1

# Calculate total attacking pairs
attacking_pairs = 0
for count in diagonal_sum.values():
    attacking_pairs += count * (count - 1) // 2

for count in diagonal_diff.values():
    attacking_pairs += count * (count - 1) // 2

print(attacking_pairs)
